let mutationFlushPending = false;
function flushPendingAddedNodes() {
  mutationFlushPending = false;
  if (pendingAddedNodes.length > PENDING_MUTATION_LIMIT) {
    /* slice and reschedule */
  }
  processAddedNodes(pendingAddedNodes);
  pendingAddedNodes = [];
}
function scheduleMutationFlush() {
  if (mutationFlushPending) return;
  mutationFlushPending = true;
  queueMicrotask(flushPendingAddedNodes);
}
mutationObserver = new MutationObserver((mutations) => {
  for (const m of mutations) for (const n of m.addedNodes ?? []) pendingAddedNodes.push(n);
  scheduleMutationFlush();
  // keep setTimeout fallback
  if (mutationTimer) clearTimeout(mutationTimer);
  mutationTimer = setTimeout(() => { scheduleMutationFlush(); }, MUTATION_DEBOUNCE_MS);
});

