function observeBlock(block, eager = false) {
  viewport.observe(block.element, {
    onEnter: () => {
      visibleElements.add(block.element);
      if (state.enabled && !block.isBound) scheduler.schedule(() => bindVisibleBlock(block), PRIORITY_VIEWPORT);
    },
  });
  if (eager && added.length <= 50) tryBindVisible(block);
}

