cases.good:
function bindVisibleBlock(block) {
  prepareBlock(block);
  if (!enabled || !visibleElements.has(block.element)) return;
  if (!block.isBound) bindTokenBlock(block, getDisplayOptions());
  if (!block.isBound) {
    // source/parent detached; evict stale block so addedNodes can create a fresh one
    const idx = blocks.indexOf(block);
    if (idx >= 0) blocks.splice(idx, 1);
    cache.delete(block.id);
    return;
  }
  cache.touch(block);
  scheduleMetadataResolve(block);
}

